const cfg = $('Set Configuration Parameters').first().json;
const response = $input.first().json;

let parsed = {
  manifest: null,
  resourceKind: 'Unknown',
  namespace: '',
  explanation: 'AI manifest generation failed to return valid JSON.'
};
try {
  const raw = String(response.output || response.text || response.response || '{}').replace(/```json|```/g, '').trim();
  const result = JSON.parse(raw);
  parsed = { ...parsed, ...result };
} catch (e) {
  // keep null manifest above; validation stage will reject it
}

return [{
  json: {
    ...cfg,
    manifest: parsed.manifest,
    resourceKind: parsed.resourceKind,
    namespace: parsed.namespace,
    explanation: parsed.explanation
  }
}];

// Deterministic, non-AI safety check. This is the actual cluster-safety
// boundary - it can never be bypassed by AI judgment, regardless of how
// confident or well-formatted the generated manifest looks.
const item = $input.first().json;
const manifest = item.manifest;
const violations = [];

if (!manifest || typeof manifest !== 'object') {
  violations.push('No valid manifest object was generated.');
} else {
  const ns = manifest.metadata?.namespace || item.namespace;
  if (!ns || !(item.allowedNamespaces || []).includes(ns)) {
    violations.push(`Namespace '${ns}' is not in the allowed namespace list.`);
  }

  const containers = manifest.spec?.template?.spec?.containers || manifest.spec?.containers || [];
  if (!Array.isArray(containers) || containers.length === 0) {
    violations.push('No containers found in the manifest.');
  }
  for (const c of containers) {
    const res = c.resources || {};
    if (!res.requests?.cpu || !res.requests?.memory) violations.push(`Container '${c.name}' is missing CPU/memory requests.`);
    if (!res.limits?.cpu || !res.limits?.memory) violations.push(`Container '${c.name}' is missing CPU/memory limits.`);
    if (c.securityContext?.privileged === true) violations.push(`Container '${c.name}' requests privileged mode - not allowed.`);
    if (c.volumeMounts && (manifest.spec?.template?.spec?.volumes || manifest.spec?.volumes || []).some(v => v.hostPath)) {
      violations.push('Manifest uses a hostPath volume - not allowed.');
    }
  }

  const podSpec = manifest.spec?.template?.spec || manifest.spec || {};
  if (podSpec.hostNetwork === true) violations.push('Manifest requests hostNetwork - not allowed.');
}

return [{
  json: {
    ...item,
    validationPassed: violations.length === 0,
    validationViolations: violations
  }
}];

