const state = $('Apply Manifest to Kubernetes').first().json;
const status = $input.first().json;

const desiredReplicas = status.spec?.replicas ?? 1;
const readyReplicas = status.status?.readyReplicas ?? 0;
const availableReplicas = status.status?.availableReplicas ?? 0;
const rolloutHealthy = readyReplicas >= desiredReplicas && availableReplicas >= desiredReplicas;

return [{
  json: {
    ...state,
    desiredReplicas,
    readyReplicas,
    availableReplicas,
    rolloutHealthy
  }
}];
